def reverse_pairs(nums):
    n = len(nums)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] > 2 * nums[j]:
                count += 1
    return count


if __name__ == "__main__":
    print(reverse_pairs([1, 3, 2, 3, 1]))
    print(reverse_pairs([2, 4, 3, 5, 1]))

