#include <bits/stdc++.h>
using namespace std;

int countPairs;

vector<int> mergeSort(vector<int>& arr) {
    if (arr.size() <= 1) return arr;

    int mid = arr.size() / 2;
    vector<int> leftHalf(arr.begin(), arr.begin() + mid);
    vector<int> rightHalf(arr.begin() + mid, arr.end());
    vector<int> left = mergeSort(leftHalf);
    vector<int> right = mergeSort(rightHalf);

    int j = 0;
    for (int i = 0; i < (int)left.size(); i++) {
        while (j < (int)right.size() && (long long)left[i] > 2LL * right[j]) j++;
        countPairs += j;
    }

    vector<int> merged;
    int li = 0, ri = 0;
    while (li < (int)left.size() && ri < (int)right.size()) {
        if (left[li] <= right[ri]) merged.push_back(left[li++]);
        else merged.push_back(right[ri++]);
    }
    while (li < (int)left.size()) merged.push_back(left[li++]);
    while (ri < (int)right.size()) merged.push_back(right[ri++]);
    return merged;
}

int reversePairs(vector<int>& nums) {
    countPairs = 0;
    mergeSort(nums);
    return countPairs;
}

int main() {
    vector<int> nums1 = {1, 3, 2, 3, 1};
    cout << reversePairs(nums1) << endl;
    vector<int> nums2 = {2, 4, 3, 5, 1};
    cout << reversePairs(nums2) << endl;
    return 0;
}
